33: static DialogResult RunZenity(std::vector<std::string>& args) {
34:   std::string cmd = "zenity";
35:   for (const std::string& arg : args) {
36:     cmd += " " + arg;
37:   }
38: 
39:   static constexpr int kBufferSize = 1024;
40:   FILE* output = popen(cmd.c_str(), "r");
41:   if (!output) {
42:     return DialogResult{.status = DialogResult::kCancelled};
43:   }
44:   char buffer[kBufferSize];
45:   auto ret = fgets(buffer, kBufferSize, output);
46:   if (ret == nullptr || ferror(output)) {
47:     return DialogResult{.status = DialogResult::kError};
48:   }
49:   // Zenity outputs a newline at the end of the buffer which we need to remove.
50:   const int len = std::strlen(buffer);
51:   if (len > 0) {
52:     buffer[len - 1] = '\0';
53:   }
54:   return DialogResult{.status = DialogResult::kAccepted,
55:                       .path = std::string(buffer)};
56: }
