44: static std::string WCharToChar(const wchar_t* str) {
45:   int wlen = static_cast<int>(wcslen(str));
46:   int num_bytes =
47:       WideCharToMultiByte(CP_UTF8, 0, str, wlen, NULL, 0, NULL, NULL);
48:   assert(num_bytes);
