57: static std::unique_ptr<wchar_t[]> CharToWChar(std::string_view str) {
58:   int len = static_cast<int>(str.size());
59:   int num_wchars = MultiByteToWideChar(CP_UTF8, 0, str.data(), len, NULL, 0);
60:   assert(num_wchars);
61:   num_wchars += 1;  // terminator
62: 
63:   wchar_t* ptr = new wchar_t[num_wchars];
64:   MultiByteToWideChar(CP_UTF8, 0, str.data(), num_wchars, ptr, num_wchars);
65:   ptr[num_wchars - 1] = '\0';
66:   return std::unique_ptr<wchar_t[]>(ptr);
