28: std::string GetModuleDir(void* addr) {
29: #if defined(_WIN32) || defined(__CYGWIN__)
30:   HMODULE hModule = NULL;
31:   if (GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
32:                          GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
33:                          (LPCSTR)addr, &hModule)) {
34:     char path[MAX_PATH];
35:     DWORD written = GetModuleFileNameA(hModule, path, sizeof(path));
36:     if (written > 0 && written < sizeof(path)) {
37:       return std::filesystem::path(path).parent_path().string();
38:     }
39:   }
40:   return "";
41: #else
42:   Dl_info info;
43:   if (dladdr(addr, &info) != 0 && info.dli_fname != nullptr) {
44:     std::filesystem::path p(info.dli_fname);
45:     if (p.is_absolute()) {
46:       return p.parent_path().string();
47:     }
48:     std::error_code ec;
49:     std::filesystem::path cwd = std::filesystem::current_path(ec);
50:     if (!ec) {
51:       return (cwd / p).parent_path().string();
52:     }
53:     return p.parent_path().string();
54:   }
55:   return "";
56: #endif
57: }
