35:     static const void* init_dlhandle = dlhandle;
36: 
37:     // check that not already initialized
38:     if (dlhandle && dlhandle != init_dlhandle) {
39:       std::cerr << "dlhandle is specified when GLFW dispatch table is already "
40:                    "initialized\n";
