50:     // load glfw dynamically
51: #ifdef mjGLFW_DYNAMIC_SYMBOLS
52:   #ifdef _MSC_VER
53:     if (!dlhandle) dlhandle = LoadLibraryA("glfw3.dll");
54:     if (!dlhandle) {
55:       std::cerr << "cannot obtain a shared object handle\n";
56:       abort();
